if [ "$(/usr/bin/xcode-select --print-path 2>&1)" = "/Library/Developer/CommandLineTools" ]; then echo "Xcode CLT already installed"; exit 0; fi; /usr/bin/touch /tmp/.com.apple.dt.CommandLineTools.installondemand.in-progress; LABEL=$(/usr/sbin/softwareupdate --list 2>&1 | /usr/bin/awk -F'Label: ' '/Label: Command Line Tools/ {print $2}' | /usr/bin/tr -d '\r' | /usr/bin/tail -1); if [ -n "$LABEL" ]; then echo "Installing: $LABEL"; /usr/sbin/softwareupdate --install "$LABEL" --verbose; else echo "No Command Line Tools label found"; fi; /bin/rm -f /tmp/.com.apple.dt.CommandLineTools.installondemand.in-progress; [ "$(/usr/bin/xcode-select --print-path 2>&1)" = "/Library/Developer/CommandLineTools" ] && echo "Xcode CLT installed successfully" || { echo "Installation failed"; exit 1; }